Code.Terraform:
```hcl
# Allow model invocation only with the approved guardrail
resource "aws_iam_policy" "<example_resource_name>" {
  name = "<example_resource_name>"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["bedrock:InvokeModel", "bedrock:InvokeModelWithResponseStream"]
      Resource = "arn:aws:bedrock:${var.region}::foundation-model/*"
      Condition = {
        StringEquals = {  # FIX: require the guardrail on every inference request
          "bedrock:GuardrailIdentifier" = "arn:aws:bedrock:${var.region}:${var.account_id}:guardrail/<example_resource_id>:1"
        }
      }
    }]
  })
}
